extension/cmd/matrix-app/main.go.content:
package main

import (
	"context"
	"errors"
	"log"
	"net/http"
	"os"
	"time"

	scaffold "github.com/7K-Hiroba/matrix-app"
)

func main() {
	if os.Getenv("SCAFFOLD_HTTP") == "true" {
		server := &http.Server{
			Addr:              ":8080",
			Handler:           scaffold.HTTPHandler(),
			ReadHeaderTimeout: 5 * time.Second,
			ReadTimeout:       10 * time.Second,
			WriteTimeout:      10 * time.Second,
			IdleTimeout:       30 * time.Second,
		}
		log.Printf("synthetic smoke server listening on %s", server.Addr)
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Fatal(err)
		}
		return
	}
	if err := scaffold.New().Serve(context.Background()); err != nil {
		log.Fatal(err)
	}
}

